look.customCSS:
/* ───── 云眸入梦 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/220px 260px,radial-gradient(ellipse at 50% 108%,#FFB8DE 0 18%,rgba(246,185,220,.55) 30%,transparent 55%),linear-gradient(180deg,#2B1F55 0%,#4A3285 45%,#8A4FA8 85%,#C46AB0 100%) !important}
[data-wk="chat"] *{font-family:"Songti SC","Noto Serif SC","STSong",serif !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：不做框，往下淡出，底下一道淡粉细线 */
[data-wk="chathead"]{position:relative !important;overflow:visible !important;background:linear-gradient(180deg,rgba(43,31,85,.9),rgba(43,31,85,0)) !important;border-bottom:none !important;box-shadow:none !important;gap:6px !important;z-index:5 !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:10% !important;right:10% !important;bottom:0 !important;height:1px !important;background:linear-gradient(90deg,transparent,rgba(255,200,230,.8),transparent) !important;pointer-events:none !important}
[data-wk="headink"],[data-wk="headink"] *{color:#fff !important}
[data-wk="headname"] > [data-wk="headink"]{font-weight:700 !important;letter-spacing:.15em !important}
[data-wk="headdim"]{color:#D8CCEC !important;white-space:nowrap !important}
[data-wk="chatback"],[data-wk="chatback"] *{color:#fff !important}
[data-wk="chatback"] svg,[data-wk="headdim"] svg{stroke:#fff !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"],[data-wk="chathead"] button:has(> [data-wk="headname"]){flex:1 1 auto !important;min-width:0 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{flex:none !important;width:36px !important;min-width:36px !important;height:36px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="chathead"] + *:not([data-wk="body"]),[data-wk="chathead"] + *:not([data-wk="body"]) *{color:#fff !important}

/* 头像：一只石头眼皮的巨眼，照片就是瞳孔，外圈一道彩虹光 */
button[data-wk="avatar"],span[data-wk="avatar"],[data-wk="rpsingle"] [data-wk="avatar"]{position:relative !important;overflow:visible !important;isolation:isolate !important;border-radius:50% !important;box-shadow:0 0 14px 3px rgba(255,200,240,.5) !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{position:relative !important;z-index:1 !important;border-radius:50% !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;left:-42% !important;right:-42% !important;top:-12% !important;bottom:-12% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:2 !important;pointer-events:none !important;border:none !important;border-radius:0 !important;filter:drop-shadow(0 3px 5px rgba(20,10,50,.45)) !important}
[data-wk="chathead"] button[data-wk="avatar"]::before,[data-wk="chathead"] span[data-wk="avatar"]::before{content:none !important}
[data-wk="chathead"] img[data-wk="avatar"]{box-shadow:0 0 0 2.5px #fff,0 0 0 5px rgba(201,138,255,.6) !important}
[data-wk="msg"] [data-wk="row"]{gap:22px !important}
[data-wk="msg"][data-me="0"] [data-wk="row"]{padding-left:12px !important}
[data-wk="msg"][data-me="1"] [data-wk="row"]{padding-right:12px !important}

/* 气泡：一朵云——上下两排圆鼓鼓的边；他的粉白云，我的暗紫雨云。一串第一条里睁着一只彩虹眼 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;isolation:isolate !important;border:none !important;border-radius:999px !important;letter-spacing:.1em !important;padding:11px 20px !important;margin:16px 16px 12px !important}
[data-wk="bubble"][data-kind="text"]::before{content:"" !important;position:absolute !important;left:8px !important;right:8px !important;top:-8px !important;bottom:-8px !important;z-index:-1 !important;border:none !important;transform:none !important;width:auto !important;height:auto !important;pointer-events:none !important;border-radius:0 !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#FDEAF4 !important;color:#5A3A70 !important;box-shadow:-9px 0 0 -1px #FDEAF4,9px 0 0 -1px #FDEAF4,0 0 22px 6px rgba(255,190,225,.5) !important;filter:none !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{background:radial-gradient(circle,#FDEAF4 10px,transparent 11px) 0 0/22px 22px round no-repeat,radial-gradient(circle,#FDEAF4 10px,transparent 11px) 0 100%/22px 22px round no-repeat !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:#5A5288 !important;color:#fff !important;box-shadow:-9px 0 0 -1px #5A5288,9px 0 0 -1px #5A5288,0 0 20px 5px rgba(150,130,220,.45) !important;filter:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{background:radial-gradient(circle,#5A5288 10px,transparent 11px) 0 0/22px 22px round no-repeat,radial-gradient(circle,#5A5288 10px,transparent 11px) 0 100%/22px 22px round no-repeat !important}
[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"]{padding-right:50px !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"]::after{content:"" !important;position:absolute !important;right:14px !important;top:50% !important;width:30px !important;height:17px !important;margin-top:-9px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:none !important;left:auto !important;bottom:auto !important;animation:ceBlink 5s ease-in-out infinite !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="1"]{padding-right:20px !important;padding-left:50px !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="1"]::after{right:auto !important;left:14px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
@keyframes ceBlink{0%,92%,100%{transform:scaleY(1)}95%{transform:scaleY(.1)}}

/* 时间：一行淡紫小字 */
[data-wk="time"] > span{background:transparent !important;border:none !important;box-shadow:none !important;color:#D8CCEC !important;letter-spacing:.3em !important;font-size:11.5px !important}
/* 已送达＝闭着的眼；已读＝睁开的彩虹眼 */
[data-wk="meta"]{color:#D8CCEC !important;font-size:11px !important;letter-spacing:.12em !important;display:inline-flex !important;align-items:center !important;gap:8px !important}
[data-wk="meta"]::after{content:"" !important;width:20px !important;height:11px !important;flex:none !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="meta"][data-read="1"]::after{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 4px rgba(255,200,240,.8)) !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:#FFE8F4 !important;border:none !important;border-radius:26px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#5A3A70 !important}
[data-wk="name"]{color:#D8CCEC !important}

/* 动描：一缕飘着的薄云，字是粉白斜体，左边一只半睁的眼 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"],[data-wk="myactink"]{position:relative !important;display:block !important;background:radial-gradient(ellipse at 50% 50%,rgba(255,220,240,.22),transparent 72%) !important;border:none !important;border-radius:40px !important;box-shadow:none !important;color:#FFE4F2 !important;font-style:italic !important;font-size:13px !important;line-height:1.9 !important;letter-spacing:.08em !important;text-shadow:0 0 8px rgba(255,190,225,.5) !important;padding:8px 18px 8px 44px !important}
[data-wk="narrink"]::before,[data-wk="myactink"]::before{content:"" !important;position:absolute !important;left:12px !important;top:50% !important;width:24px !important;height:13px !important;margin-top:-7px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:.85 !important}
[data-wk="myactink"]{padding:8px 44px 8px 18px !important;text-align:right !important}
[data-wk="myactink"]::before{left:auto !important;right:12px !important}
[data-wk="narrbar"]{background:rgba(43,31,85,.95) !important;border-top:1px solid rgba(255,200,230,.4) !important}
[data-wk="narrkind"]{border:1px solid rgba(216,204,236,.5) !important;border-radius:999px !important;background:transparent !important;color:#D8CCEC !important}
[data-wk="narrkind"][data-on="1"]{background:#FFE8F4 !important;border-color:#FFE8F4 !important;color:#5A3A70 !important}
/* 系统提示：一行小字，两头各一颗星 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{display:inline-block !important;background:radial-gradient(circle,#fff 1.4px,transparent 2px) left center/8px 8px no-repeat,radial-gradient(circle,#fff 1.4px,transparent 2px) right center/8px 8px no-repeat !important;border:none !important;color:#D8CCEC !important;font-size:11px !important;font-style:normal !important;letter-spacing:.12em !important;padding:0 16px !important}
[data-wk="sysnoteclose"]{color:#D8CCEC !important}

/* 底栏：不做框，往上透出底下那片粉云，上沿一道淡粉线；最右「让他回复」＝粉云里睁着的大眼 */
[data-wk="composer"]{position:relative !important;background:linear-gradient(180deg,rgba(196,106,176,0),rgba(150,80,160,.6)) !important;border-top:none !important;box-shadow:none !important;align-items:center !important;gap:10px !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:10% !important;right:10% !important;top:0 !important;height:1px !important;background:linear-gradient(90deg,transparent,rgba(255,200,230,.8),transparent) !important;pointer-events:none !important}
[data-wk="chatinput"]{background:rgba(255,255,255,.14) !important;border:1px solid rgba(255,220,240,.6) !important;border-radius:999px !important;color:#fff !important}
[data-wk="chatinput"]::placeholder{color:#F4DDF0 !important}
[data-wk="chatplus"],[data-wk="send"],[data-wk="chatreply"]{border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{width:36px !important;min-width:36px !important;height:36px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{width:36px !important;min-width:36px !important;height:36px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:52px !important;min-width:52px !important;height:44px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 10px rgba(255,200,235,.8)) !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.9) !important}
[data-wk="chatpanel"]{background:rgba(43,31,85,.96) !important;border-top:1px solid rgba(255,200,230,.4) !important}
[data-wk="quotedraft"]{position:relative !important;z-index:3 !important}
